    if (!isOut && T.inBorder) { ctx.strokeStyle = T.inBorder; ctx.lineWidth = 1; bubblePath(ctx, x, y, el.w, el.h, el.side); ctx.stroke(); }
    ctx.font = FONT_MSG; ctx.fillStyle = isOut ? T.outText : T.inText; ctx.textBaseline = "alphabetic"; ctx.textAlign = "left";
    let ty = y + BUB_PADTOP + 34; for (const l of el.lines) { ctx.fillText(l, x + BUB_PADX, ty); ty += LINE_H; }
    ctx.font = FONT_META; ctx.textAlign = "right";
