    if (isOut) { const tw = ctx.measureText("✓✓").width; ctx.fillStyle = T.tick; ctx.fillText("✓✓", rightX, metaY); ctx.fillStyle = T.metaOut; ctx.fillText(el.time, rightX - tw - 8, metaY); }
