    const AC = window.AudioContext || window.webkitAudioContext; if (!AC) return null;
    const ctx = new AC(); const master = ctx.createGain(); master.gain.value = 0.95;
    const dest = ctx.createMediaStreamDestination(); master.connect(ctx.destination); master.connect(dest);
    const blips = ctx.createGain(); blips.gain.value = soundRef.current ? 0.9 : 0; blips.connect(master);
    const music = ctx.createGain(); music.gain.value = musicVolRef.current; music.connect(master);
