  async function handleRecord() {
    if (busy) return;
    if (!canRecord()) { setStatus("This browser can't record canvas video. Try Chrome or Edge on desktop."); return; }
    setVideoUrl(null); setBusy(true); setMode("record"); setStatus("Recording…");
    try { const { blob, ext } = await recordOnce(); setVideoUrl(URL.createObjectURL(blob)); setVideoExt(ext); setStatus(ext === "mp4" ? "Video ready — use the Download menu." : "Video ready (.webm) — use the Download menu."); }
    catch (e) { setStatus("Recording failed: " + (e.message || e)); }
    setBusy(false); setMode(null);
  }
  function saveBlob(blob, name) { const u = URL.createObjectURL(blob); const el = document.createElement("a"); el.href = u; el.download = name; el.click(); setTimeout(() => URL.revokeObjectURL(u), 5000); }
  function saveDataUrl(url, name) { const el = document.createElement("a"); el.href = url; el.download = name; el.click(); }

  // --- JPG export (fixed) ---------------------------------------------------
  // A several-hundred-KB data: URL on a detached <a> is silently dropped by
  // Chrome, so JPG export goes through a Blob on an anchor that's actually in
  // the document. The redraw loop is required too: drawFrame moves the scroll
  // by a 20%/frame lerp and buildTimeline resets it to 0, so a single draw
  // would capture the chat scrolled only a fifth of the way down.
