    try { const rr = await fetch(musicUrl.trim()); const buf = await rr.arrayBuffer(); a.ctx.decodeAudioData(buf, (dec) => { musicBufRef.current = dec; setMusic("custom"); setStatus("Music loaded from URL."); }, () => setStatus("Couldn't decode that audio URL.")); }
